create type public.app_role as enum ('owner','manager','receptionist','trainer','member');
create table public.gyms (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, name_hi text, phone text, whatsapp text, address text, city text, state text, postal_code text, country text not null default 'India', timezone text not null default 'Asia/Kolkata', created_at timestamptz not null default now());
grant select on public.gyms to anon,authenticated; grant update on public.gyms to authenticated; grant all on public.gyms to service_role;
alter table public.gyms enable row level security;
create policy "public gym identity" on public.gyms for select to anon,authenticated using (true);
create table public.gym_settings (gym_id uuid primary key references public.gyms(id) on delete cascade, hours jsonb not null default '[]', about_text text, trial_slots jsonb not null default '["Morning","Evening"]', trial_slot_capacity integer not null default 5 check (trial_slot_capacity between 1 and 100), checkin_cooldown_minutes integer not null default 240 check (checkin_cooldown_minutes between 1 and 1440), expiring_soon_days integer not null default 7, entrance_qr_ttl_seconds integer not null default 30, updated_at timestamptz not null default now());
grant select on public.gym_settings to anon,authenticated; grant update on public.gym_settings to authenticated; grant all on public.gym_settings to service_role;
alter table public.gym_settings enable row level security;
create policy "public settings" on public.gym_settings for select to anon,authenticated using (true);
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, avatar_url text);
grant select,insert,update on public.profiles to authenticated; grant all on public.profiles to service_role;
alter table public.profiles enable row level security;
create policy "own profile read" on public.profiles for select to authenticated using (id=auth.uid());
create policy "own profile insert" on public.profiles for insert to authenticated with check (id=auth.uid());
create policy "own profile update" on public.profiles for update to authenticated using (id=auth.uid()) with check (id=auth.uid());
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, gym_id uuid not null references public.gyms(id) on delete cascade, role public.app_role not null, unique(user_id,gym_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create function public.has_gym_role(_gym uuid,_roles public.app_role[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and gym_id=_gym and role=any(_roles)) $$;
revoke all on function public.has_gym_role(uuid,public.app_role[]) from public,anon; grant execute on function public.has_gym_role(uuid,public.app_role[]) to authenticated;
create policy "own roles" on public.user_roles for select to authenticated using (user_id=auth.uid());
create policy "owner updates gym" on public.gyms for update to authenticated using (public.has_gym_role(id,array['owner']::public.app_role[])) with check (public.has_gym_role(id,array['owner']::public.app_role[]));
create policy "admin updates settings" on public.gym_settings for update to authenticated using (public.has_gym_role(gym_id,array['owner','manager']::public.app_role[])) with check (public.has_gym_role(gym_id,array['owner','manager']::public.app_role[]));
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name')) on conflict do nothing; return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
revoke all on function public.handle_new_user() from public,anon,authenticated;
create table public.membership_plans (id uuid primary key default gen_random_uuid(),gym_id uuid not null references public.gyms(id), name text not null, category text not null default 'monthly', duration_days integer not null check(duration_days>0), price numeric(10,2) not null check(price>=0), joining_fee numeric(10,2) not null default 0, features text[] not null default '{}', is_recommended boolean not null default false, is_published boolean not null default false, sort_order integer not null default 0, archived_at timestamptz);
grant select on public.membership_plans to anon; grant select,insert,update,delete on public.membership_plans to authenticated; grant all on public.membership_plans to service_role;
alter table public.membership_plans enable row level security;
create table public.facilities (id uuid primary key default gen_random_uuid(),gym_id uuid not null references public.gyms(id), name text not null, description text, image_url text, is_published boolean not null default false, sort_order integer not null default 0);
grant select on public.facilities to anon; grant select,insert,update,delete on public.facilities to authenticated; grant all on public.facilities to service_role;
alter table public.facilities enable row level security;
create table public.trainers (id uuid primary key default gen_random_uuid(),gym_id uuid not null references public.gyms(id), user_id uuid, full_name text not null, specialization text, qualifications text, photo_url text, experience_years integer, is_published boolean not null default false, is_active boolean not null default true);
grant select on public.trainers to anon; grant select,insert,update,delete on public.trainers to authenticated; grant all on public.trainers to service_role;
alter table public.trainers enable row level security;
create table public.testimonials (id uuid primary key default gen_random_uuid(),gym_id uuid not null references public.gyms(id),author_name text not null,quote text not null,rating integer check(rating between 1 and 5),source text,consent_confirmed boolean not null default false,is_published boolean not null default false check(not is_published or consent_confirmed));
grant select on public.testimonials to anon; grant select,insert,update,delete on public.testimonials to authenticated; grant all on public.testimonials to service_role;
alter table public.testimonials enable row level security;
create table public.transformation_stories (id uuid primary key default gen_random_uuid(),gym_id uuid not null references public.gyms(id),title text not null,story text not null,image_url text,consent_confirmed boolean not null default false,is_published boolean not null default false check(not is_published or consent_confirmed));
grant select on public.transformation_stories to anon; grant select,insert,update,delete on public.transformation_stories to authenticated; grant all on public.transformation_stories to service_role;
alter table public.transformation_stories enable row level security;
create table public.faqs (id uuid primary key default gen_random_uuid(),gym_id uuid not null references public.gyms(id),question text not null,answer text not null,is_published boolean not null default false,sort_order integer not null default 0);
grant select on public.faqs to anon; grant select,insert,update,delete on public.faqs to authenticated; grant all on public.faqs to service_role;
alter table public.faqs enable row level security;
do $$ declare t text; begin foreach t in array array['membership_plans','facilities','trainers','testimonials','transformation_stories','faqs'] loop execute format('create policy "published content" on public.%I for select to anon,authenticated using(is_published)',t); execute format('create policy "staff read drafts" on public.%I for select to authenticated using(public.has_gym_role(gym_id,array[''owner'',''manager'',''receptionist'',''trainer'']::public.app_role[]))',t); execute format('create policy "admin manages content" on public.%I for all to authenticated using(public.has_gym_role(gym_id,array[''owner'',''manager'']::public.app_role[])) with check(public.has_gym_role(gym_id,array[''owner'',''manager'']::public.app_role[]))',t); end loop; end $$;
create table public.leads (id uuid primary key default gen_random_uuid(),gym_id uuid not null references public.gyms(id),full_name text not null,phone text not null,email text,source text not null default 'website',stage text not null default 'new',fitness_goal text,notes text,consent_to_contact boolean not null default false,created_at timestamptz not null default now());
grant select,insert,update on public.leads to authenticated; grant all on public.leads to service_role;
alter table public.leads enable row level security;
create table public.trial_bookings (id uuid primary key default gen_random_uuid(),gym_id uuid not null references public.gyms(id),lead_id uuid references public.leads(id),full_name text not null,phone text not null,email text,preferred_date date not null,time_slot text not null,fitness_goal text,status text not null default 'pending' check(status in('pending','confirmed','completed','no_show','cancelled')),created_at timestamptz not null default now(),unique(gym_id,phone,preferred_date));
grant select,insert,update on public.trial_bookings to authenticated; grant all on public.trial_bookings to service_role;
alter table public.trial_bookings enable row level security;
create table public.contact_messages (id uuid primary key default gen_random_uuid(),gym_id uuid not null references public.gyms(id),full_name text not null,phone text not null,email text,message text not null,handled boolean not null default false,created_at timestamptz not null default now());
grant select,insert,update on public.contact_messages to authenticated; grant all on public.contact_messages to service_role;
alter table public.contact_messages enable row level security;
create table public.audit_logs (id uuid primary key default gen_random_uuid(),gym_id uuid references public.gyms(id),actor_id uuid,action text not null,entity text,entity_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
grant select on public.audit_logs to authenticated; grant all on public.audit_logs to service_role;
alter table public.audit_logs enable row level security;
create policy "admin audit read" on public.audit_logs for select to authenticated using(public.has_gym_role(gym_id,array['owner','manager']::public.app_role[]));
do $$ declare t text; begin foreach t in array array['leads','trial_bookings','contact_messages'] loop execute format('create policy "front desk manages enquiries" on public.%I for all to authenticated using(public.has_gym_role(gym_id,array[''owner'',''manager'',''receptionist'']::public.app_role[])) with check(public.has_gym_role(gym_id,array[''owner'',''manager'',''receptionist'']::public.app_role[]))',t); end loop; end $$;
create index on public.leads(gym_id,phone,created_at); create index on public.trial_bookings(gym_id,preferred_date,time_slot); create index on public.contact_messages(gym_id,phone,created_at);
create function public.submit_public_request(_slug text,_kind text,_name text,_phone text,_email text,_message text,_date date,_slot text,_consent boolean) returns jsonb language plpgsql security definer set search_path=public as $$
declare g uuid; setting record; rid uuid; lid uuid; today date; recent integer;
begin
 if _kind not in('enquiry','trial') or not coalesce(_consent,false) then raise exception 'Please consent to being contacted'; end if;
 if length(trim(_name)) not between 2 and 120 or _phone !~ '^\+?[0-9]{10,15}$' or length(coalesce(_email,''))>254 or length(coalesce(_message,''))>2000 then raise exception 'Please check your contact details'; end if;
 if _kind='enquiry' and length(trim(coalesce(_message,'')))<5 then raise exception 'Please enter your enquiry'; end if;
 select id into g from public.gyms where slug=_slug;
 if g is null then raise exception 'Gym unavailable'; end if;
 perform pg_advisory_xact_lock(hashtextextended(g::text||_phone,0));
 select (select count(*) from public.leads where gym_id=g and phone=_phone and created_at>now()-interval '1 hour')+(select count(*) from public.contact_messages where gym_id=g and phone=_phone and created_at>now()-interval '1 hour') into recent;
 if recent>=3 then raise exception 'Too many requests. Please call the gym or try again later'; end if;
 if _kind='trial' then
  select * into setting from public.gym_settings where gym_id=g;
  today:=(now() at time zone 'Asia/Kolkata')::date;
  if _date is null or _date<today or _date>today+30 then raise exception 'Choose a date within the next 30 days'; end if;
  if not coalesce(setting.trial_slots ? _slot,false) then raise exception 'Choose an available preference'; end if;
  perform pg_advisory_xact_lock(hashtextextended(g::text||_date::text||_slot,0));
  if exists(select 1 from public.trial_bookings where gym_id=g and phone=_phone and preferred_date=_date) then raise exception 'You already requested a trial on this date'; end if;
  if (select count(*) from public.trial_bookings where gym_id=g and preferred_date=_date and time_slot=_slot and status in('pending','confirmed'))>=setting.trial_slot_capacity then raise exception 'This preference is full. Choose another date or preference'; end if;
  insert into public.leads(gym_id,full_name,phone,email,fitness_goal,consent_to_contact,stage) values(g,trim(_name),_phone,nullif(_email,''),_message,true,'trial_scheduled') returning id into lid;
  insert into public.trial_bookings(gym_id,lead_id,full_name,phone,email,preferred_date,time_slot,fitness_goal) values(g,lid,trim(_name),_phone,nullif(_email,''),_date,_slot,_message) returning id into rid;
 else
  insert into public.contact_messages(gym_id,full_name,phone,email,message) values(g,trim(_name),_phone,nullif(_email,''),trim(_message)) returning id into rid;
 end if;
 insert into public.audit_logs(gym_id,action,entity,entity_id) values(g,'website.'||_kind||'_submitted',_kind,rid);
 return jsonb_build_object('reference',rid,'status','received');
end $$;
revoke all on function public.submit_public_request(text,text,text,text,text,text,date,text,boolean) from public;
grant execute on function public.submit_public_request(text,text,text,text,text,text,date,text,boolean) to anon,authenticated;
create function public.validate_contact_fields() returns trigger language plpgsql set search_path=public as $$ begin if length(trim(new.full_name)) not between 2 and 120 or new.phone !~ '^\+?[0-9]{10,15}$' or (new.email is not null and (length(new.email)>254 or new.email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')) then raise exception 'Please check your contact details'; end if; return new; end $$;
create trigger validate_lead before insert or update on public.leads for each row execute function public.validate_contact_fields();
create trigger validate_trial before insert or update on public.trial_bookings for each row execute function public.validate_contact_fields();
create trigger validate_enquiry before insert or update on public.contact_messages for each row execute function public.validate_contact_fields();
create function public.audit_request_update() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.audit_logs(gym_id,actor_id,action,entity,entity_id) values(new.gym_id,auth.uid(),'request.updated',tg_table_name,new.id); return new; end $$;
revoke all on function public.audit_request_update() from public,anon,authenticated;
create trigger trial_update_audit after update on public.trial_bookings for each row execute function public.audit_request_update();
create trigger contact_update_audit after update on public.contact_messages for each row execute function public.audit_request_update();
create index membership_plans_gym_idx on public.membership_plans(gym_id); create index facilities_gym_idx on public.facilities(gym_id); create index trainers_gym_idx on public.trainers(gym_id); create index testimonials_gym_idx on public.testimonials(gym_id); create index stories_gym_idx on public.transformation_stories(gym_id); create index faqs_gym_idx on public.faqs(gym_id); create index audit_gym_idx on public.audit_logs(gym_id,created_at desc); create index roles_gym_idx on public.user_roles(gym_id); create index trial_lead_idx on public.trial_bookings(lead_id);